<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\Holder\TrustedClientAllowedRedirectsUrlAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TrustedClientAllowedRedirectsUrlAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class TrustedClientAllowedRedirectsUrlAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getUrl returns null on a freshly created holder.
     */
    public function testUrlNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientAllowedRedirectsUrlAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isUrlAssigned());
        $this->assertNull($holder->getUrl());
    }
}
class ImplWithTrustedClientAllowedRedirectsUrlAttributeHolderUnitTest
{
    use TrustedClientAllowedRedirectsUrlAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedUrlRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultUrl();
    }
}
